export const depensesCreate = async (nouvelleDepense: NouvelleDepense, options?: Parameters<typeof optiboulFetch>[1]): Promise<depensesCreateResponse> => {
    const formData = new FormData();
formData.append(`categorie`, nouvelleDepense.categorie);
formData.append(`libelle`, nouvelleDepense.libelle);
formData.append(`montant`, nouvelleDepense.montant.toString())
formData.append(`paye_par`, nouvelleDepense.paye_par);
formData.append(`rattachement`, nouvelleDepense.rattachement);
if(nouvelleDepense.matiere !== undefined) {
 formData.append(`matiere`, nouvelleDepense.matiere);
 }
if(nouvelleDepense.quantite !== undefined && nouvelleDepense.quantite !== null) {
 formData.append(`quantite`, nouvelleDepense.quantite);
 }
if(nouvelleDepense.fournisseur !== undefined) {
 formData.append(`fournisseur`, nouvelleDepense.fournisseur);
 }
if(nouvelleDepense.justificatif !== undefined && nouvelleDepense.justificatif !== null) {
 formData.append(`justificatif`, nouvelleDepense.justificatif);
 }

  return optiboulFetch<depensesCreateResponse>(getDepensesCreateUrl(),
  {
    ...options,
    method: 'POST'
    ,
    body: formData
  }
);}





